const rows = msg.payload;
for (const r of rows) {
  const bus = Number(r.bus);
  node.send({ topic: 'True (GridPACK)', payload: Number(r.sent_v), x: bus, y: Number(r.sent_v) });
  if (r.delivered == 1 && r.recv_v !== '') {
    node.send({ topic: 'Delivered (NS-3)', payload: Number(r.recv_v), x: bus, y: Number(r.recv_v) });
  }
}
return null;

const rows = msg.payload;
for (const r of rows) {
    const bus = Number(r.bus);
    if (r.delivered == 1 && r.delay_ms !== '' && r.delay_ms != null) {
        // delivered: Normal or Problem bus
        const isProblem = (Number(r.sent_v) > 1.08) || (r.attacked == 1);
        node.send({
            topic: isProblem ? 'Problem bus' : 'Normal',
            payload: Number(r.delay_ms),
            x: bus,
            y: Number(r.delay_ms)
        });
    } else {
        // lost: show a small marker so the gap is visible and labeled
        node.send({
            topic: 'Lost',
            payload: 0,
            x: bus,
            y: 1   // small fixed height so it's visible but clearly not a real delay
        });
    }
}
return null;

const rows = msg.payload;
let html = `<div style="display:flex;justify-content:center;width:100%"><table style="border-collapse:collapse;font-size:14px;margin:0 auto">
<tr style="background:#0d47a1;color:#fff">
<th style="padding:6px;border:1px solid #ccc">Bus</th>
<th style="padding:6px;border:1px solid #ccc">True V</th>
<th style="padding:6px;border:1px solid #ccc">Recv V</th>
<th style="padding:6px;border:1px solid #ccc">Delay ms</th>
<th style="padding:6px;border:1px solid #ccc">Status</th></tr>`;
for (const r of rows) {
  const lost = (r.delivered != 1);
  const atk = (r.attacked == 1);
  let bg = '', status = 'OK', scolor = '#2e7d32';
  if (lost) { bg = 'background:#ffcdd2'; status = 'LOST'; scolor = '#c62828'; }
  else if (atk) { bg = 'background:#fff3cd'; status = '⚠ TAMPERED'; scolor = '#e65100'; }
  html += `<tr style="${bg}">
<td style="padding:5px;border:1px solid #ccc;text-align:center">${r.bus}</td>
<td style="padding:5px;border:1px solid #ccc;text-align:center">${Number(r.sent_v).toFixed(4)}</td>
<td style="padding:5px;border:1px solid #ccc;text-align:center">${lost ? '—' : Number(r.recv_v).toFixed(4)}</td>
<td style="padding:5px;border:1px solid #ccc;text-align:center">${lost ? '—' : Number(r.delay_ms).toFixed(2)}</td>
<td style="padding:5px;border:1px solid #ccc;text-align:center;font-weight:bold;color:${scolor}">${status}</td></tr>`;
}
html += `</table></div>`;
msg.payload = html;
return msg;

const s = msg.payload;
const rate = (s.delivered / s.total_buses) * 100;
msg.payload = Math.round(rate * 10) / 10;   
return msg;

const s = msg.payload;
const attackLine = (s.attack && s.attack !== 'none')
    ? `⚠ ATTACK: ${s.attack} — MISSED violations: ${s.missed_violations}`
    : `Security: no attack detected`;
const line1 = `Delivered: ${s.delivered}/${s.total_buses} &nbsp; | &nbsp; Lost: ${s.lost} (${Number(s.loss_actual_pct).toFixed(1)}%) &nbsp; | &nbsp; Violations seen: ${s.violations_seen_by_pdc} &nbsp; | &nbsp; Avg delay: ${Number(s.avg_delay_ms).toFixed(2)} ms`;
msg.payload = `<div style="font-size:14px;line-height:1.6">${line1}<br><span style="color:#c62828;font-weight:bold">${attackLine}</span></div>`;
return msg;

const s = msg.payload;
const sec = (s.attack && s.attack !== 'none') ? '🔴 UNDER ATTACK' : '🟢 SECURE';
msg.payload = `Scenario: ${s.scenario}  |  Latency: ${s.latency_ms} ms  |  ${sec}  |  HELICS: ${s.helics_status}`;
return msg;

// validate dashboard input and build the run_scenario_docker.sh arguments
if (flow.get('running')) {
    return [null, { status: { running: true, text: 'A scenario is already running…' } }];
}
const p = msg.payload || {};
const name = String(p.name || 'web').replace(/[^A-Za-z0-9_-]/g, '').slice(0, 40) || 'web';
const latency = Number(p.latency), loss = Number(p.loss), drop = Math.trunc(Number(p.droppmu) || 0);
if (!(latency >= 0 && latency <= 5000)) return [null, { status: { error: true, text: 'Latency must be 0–5000 ms.' } }];
if (!(loss >= 0 && loss <= 1)) return [null, { status: { error: true, text: 'Loss must be between 0 and 1.' } }];
if (!(drop >= 0 && drop <= 14)) return [null, { status: { error: true, text: 'Drop bus must be 0–14.' } }];

let args = `--latency=${latency} --loss=${loss} --name=${name}`;
if (p.attack) args += ' --attack=1';
if (drop > 0) args += ` --droppmu=${drop}`;

flow.set('running', true);
return [{ payload: args },
        { status: { running: true, text: `Running "${name}" (latency ${latency} ms, loss ${loss}${p.attack ? ', FDI attack' : ''}${drop ? ', drop bus ' + drop : ''})…` } }];

// exec finished: release the lock, report, and reload the dashboard data
flow.set('running', false);
const code = msg.payload && msg.payload.code;
if (code === 0) {
    return [{ status: { text: 'Scenario complete — dashboard updated at ' + new Date().toLocaleTimeString() + '.' } }, { payload: Date.now() }];
}
return [{ status: { error: true, text: 'Scenario failed (exit code ' + code + '). Check the Node-RED debug panel.' } }, null];

