.cps { font-size: 14px; color: #263238; width: 100%; }
.cps .sub, .cps-line.sub { color: #78909c; font-size: 12px; font-weight: normal; }
.cps-scroll { overflow-x: auto; width: 100%; }
.cps-tbl { border-collapse: collapse; width: 100%; font-size: 13px; }
.cps-tbl th { text-align: left; font-weight: 600; color: #546e7a; border-bottom: 2px solid #cfd8dc; padding: 6px 8px; white-space: nowrap; }
.cps-tbl td { border-bottom: 1px solid #eceff1; padding: 6px 8px; vertical-align: top; }
.cps-tbl .r { text-align: right; font-variant-numeric: tabular-nums; }
.cps-tbl td.bad { color: #c62828; font-weight: 600; }
.cps-click tbody tr { cursor: pointer; }
.cps-click tbody tr:hover { background: #f5f9ff; }
.cps-click tbody tr.sel { background: #e3f2fd; }
.cps-empty { color: #90a4ae; padding: 12px 4px; }
.cps-err { color: #b71c1c; background: #ffebee; border-radius: 4px; padding: 8px 10px; }
.cps-ok { color: #1b5e20; background: #e8f5e9; border-radius: 4px; padding: 8px 10px; }
.cps-chip { display: inline-block; border-radius: 10px; padding: 1px 8px; font-size: 12px; background: #eceff1; color: #37474f; white-space: nowrap; }
.cps-chip.q { background: #fff8e1; color: #8d6e00; }
.cps-chip.run { background: #e3f2fd; color: #0d47a1; }
.cps-chip.ok { background: #e8f5e9; color: #1b5e20; }
.cps-chip.bad { background: #ffebee; color: #b71c1c; }
.cps-chip.role { background: #ede7f6; color: #4527a0; }
.cps-chip.tag { background: #eceff1; }
.cps-log { margin: 0; font-size: 11px; max-width: 420px; white-space: pre-wrap; word-break: break-all; color: #546e7a; }
.cps-nodes { display: flex; flex-wrap: wrap; gap: 10px; }
.cps-node { border: 1px solid #cfd8dc; border-radius: 6px; padding: 8px 12px; min-width: 170px; }
.cps-node .h { font-weight: 600; font-size: 15px; display: flex; align-items: center; gap: 6px; }
.cps-node .dot { width: 9px; height: 9px; border-radius: 50%; background: #2e7d32; display: inline-block; }
.cps-node.down .dot { background: #c62828; }
.cps-node .roles { margin-top: 4px; display: flex; flex-wrap: wrap; gap: 4px; }
.cps-line { margin-top: 10px; }
.cps-help p { margin: 0 0 8px; line-height: 1.45; }
.cps-help code, .cps code { background: #eceff1; border-radius: 3px; padding: 0 4px; font-size: 12px; }
.cps-title { font-size: 17px; font-weight: 600; margin-bottom: 6px; }
.cps-tags { display: flex; flex-wrap: wrap; gap: 4px; margin-bottom: 10px; }
.cps-kpis { display: grid; grid-template-columns: repeat(auto-fill, minmax(150px, 1fr)); gap: 8px; }
.cps-kpi { border-radius: 6px; padding: 8px 10px; background: #f5f7f8; border-left: 4px solid #b0bec5; }
.cps-kpi .v { font-size: 18px; font-weight: 600; font-variant-numeric: tabular-nums; }
.cps-kpi .l { font-size: 12px; color: #607d8b; }
.cps-kpi.good { border-left-color: #2e7d32; background: #f1f8f2; }
.cps-kpi.warn { border-left-color: #f9a825; background: #fffbea; }
.cps-kpi.bad { border-left-color: #c62828; background: #fdf0f0; }
.cps-charts { display: grid; grid-template-columns: repeat(auto-fit, minmax(320px, 1fr)); gap: 14px; }
.cps-chart.wide { grid-column: 1 / -1; }
.cps-profctl { display: flex; gap: 8px; align-items: center; flex-wrap: wrap; margin-bottom: 10px; }
.cps-profctl input[type=range] { flex: 1; min-width: 160px; }
.cps-profctl .cps-tin { width: 90px; border: 1px solid #b0bec5; border-radius: 4px; padding: 3px 6px; }
.cps-chart svg { width: 100%; height: auto; display: block; }
.cps-ctitle { font-weight: 600; font-size: 13px; color: #37474f; margin-bottom: 2px; }
.cps-chart .cps-grid { stroke: #eceff1; stroke-width: 1; }
.cps-chart .cps-axis { stroke: #90a4ae; stroke-width: 1; }
.cps-chart .cps-tick { font-size: 15px; fill: #78909c; }
.cps-chart .cps-lbl { font-size: 15px; fill: #546e7a; }
.cps-chart .cps-band { fill: #ffcdd2; opacity: 0.45; }
.cps-legend { display: flex; flex-wrap: wrap; gap: 12px; font-size: 12px; color: #546e7a; margin-top: 2px; }
.cps-key { display: inline-flex; align-items: center; gap: 5px; }
.cps-key i { width: 14px; height: 3px; display: inline-block; }
.cps-key i.dash { height: 0; border-top: 2px dashed; }
.cps-key i.band { height: 10px; background: #ffcdd2; }
.cps-progress { height: 6px; background: #eceff1; border-radius: 3px; overflow: hidden; margin: 2px 0 10px; }
.cps-progress div { height: 100%; background: #1565c0; transition: width 0.4s; }
.cps-runbtn { border: 1px solid #cfd8dc; border-radius: 12px; padding: 2px 10px; font-size: 12px; background: #fff; cursor: pointer; }
.cps-runbtn.sel { background: #e3f2fd; border-color: #1565c0; }
/* experiment form and cluster settings */
.cps-form .cps-presets { display: flex; flex-wrap: wrap; gap: 6px; align-items: center; margin-bottom: 10px; }
.cps-form .cps-presets .lbl { color: #546e7a; font-size: 13px; margin-right: 4px; }
.cps-form .cps-fgrid { display: grid; grid-template-columns: repeat(auto-fit, minmax(240px, 1fr)); gap: 10px; }
.cps-form fieldset { border: 1px solid #cfd8dc; border-radius: 6px; padding: 6px 10px 10px; margin: 0; min-width: 0; }
.cps-form legend { font-weight: 600; font-size: 13px; color: #37474f; padding: 0 4px; }
.cps-form label { display: block; font-size: 12px; color: #546e7a; margin-top: 6px; }
.cps-form label.chk { display: flex; gap: 6px; align-items: center; color: #37474f; font-size: 13px; }
.cps-form input:not([type=checkbox]), .cps-form select { display: block; width: 100%; box-sizing: border-box; margin-top: 2px;
  border: 1px solid #b0bec5; border-radius: 4px; padding: 5px 6px; font-size: 14px; color: #263238; background: #fff; }
.cps-form .hint { font-size: 12px; color: #78909c; margin-top: 6px; line-height: 1.35; }
.cps-form .cps-factions { display: flex; flex-wrap: wrap; gap: 10px; align-items: center; margin: 12px 0 8px; }
.cps-go { background: #1565c0; color: #fff; border: 0; border-radius: 4px; padding: 8px 18px; font-size: 14px; font-weight: 600; cursor: pointer; }
.cps-go:disabled { background: #90a4ae; cursor: default; }
.cps-link { color: #1565c0; font-weight: 600; text-decoration: none; }
.cps-noderow { display: grid; grid-template-columns: 1fr 70px auto; gap: 6px; margin-bottom: 6px; align-items: center; }
.cps-noderow input { margin-top: 0 !important; }
/* Inside page */
.cps-flow { width: 100%; max-width: 900px; height: auto; display: block; margin: 4px auto 6px; }
.cps-fbox { fill: #e3f2fd; stroke: #1565c0; stroke-width: 1.5; }
.cps-fbox.obs { fill: #f5f5f5; stroke: #90a4ae; }
.cps-ftitle { font-size: 16px; font-weight: 600; fill: #263238; }
.cps-fsub { font-size: 12px; fill: #546e7a; }
.cps-ftime { font-size: 13px; fill: #0d47a1; font-weight: 600; }
.cps-alabel { font-size: 11px; fill: #455a64; }
.cps-alabel .tn { font-weight: 600; fill: #263238; }
.cps-sect { font-weight: 600; font-size: 13px; color: #37474f; margin: 12px 0 6px; }
.cps-rank { display: grid; grid-template-columns: 60px 90px 1fr 170px; gap: 8px; align-items: center; font-size: 13px; margin-bottom: 4px; }
.cps-rank .rn { font-weight: 600; } .cps-rank .rh { color: #546e7a; } .cps-rank .rv { color: #546e7a; font-size: 12px; }
.cps-rank .rb { background: #eceff1; height: 10px; border-radius: 5px; overflow: hidden; }
.cps-rank .rb i { display: block; height: 100%; background: #2e7d32; }
.cps-pmus { display: flex; flex-wrap: wrap; gap: 3px; margin-bottom: 6px; }
.cps-pmu { min-width: 26px; height: 22px; padding: 0 3px; border-radius: 3px; font-size: 11px; line-height: 22px; text-align: center; color: #fff; background: #43a047; cursor: default; }
.cps-pmus:has(.cps-pmu:nth-child(81)) .cps-pmu { min-width: 10px; height: 10px; padding: 0; }
.cps-pmu.late { background: #f9a825; } .cps-pmu.lost { background: #e53935; } .cps-pmu.drop { background: #6d4c41; }
.cps-pmu.atk { background: #8e24aa; } .cps-pmu.idle { background: #b0bec5; }
.cps-key i.sq { width: 10px; height: 10px; border-radius: 2px; }
.cps-key i.sq.ok { background: #43a047; } .cps-key i.sq.late { background: #f9a825; } .cps-key i.sq.lost { background: #e53935; }
.cps-key i.sq.drop { background: #6d4c41; } .cps-key i.sq.atk { background: #8e24aa; }
.cps-trace.key { max-height: 360px; }
.cps-trace { max-height: 420px; overflow-y: auto; font-size: 13px; }
.cps-trace .row { display: grid; grid-template-columns: 64px 118px 1fr; gap: 6px; padding: 4px 0; border-bottom: 1px solid #eceff1; align-items: start; }
.cps-trace .t { color: #78909c; font-variant-numeric: tabular-nums; text-align: right; }
.cps-chip.eng.gp { background: #e8f5e9; color: #1b5e20; } .cps-chip.eng.ns { background: #e0f2f1; color: #004d40; }
.cps-chip.eng.cc { background: #f3e5f5; color: #4a148c; } .cps-chip.eng.hx { background: #e3f2fd; color: #0d47a1; }

