// Shared helpers for the cluster pages, stored in global context as "cps":
// API requests, HTML escaping, number formatting, tables and inline SVG charts.
// Everything rendered from API data goes through esc(), because grid and run names
// come from uploaded files.
const esc = (s) => String(s === null || s === undefined ? '' : s)
    .replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));

const num = (v, d = 2) => (v === null || v === undefined || Number.isNaN(Number(v)))
    ? '–' : String(Number(Number(v).toFixed(d)));

const api = (msg, method, path, body) => {
    const base = env.get('CPS_API') || 'http://127.0.0.1:8080';
    msg.method = method;
    msg.url = base + path;
    msg.headers = { 'Content-Type': 'application/json' };
    const pw = env.get('CPS_WEB_PASSWORD');
    if (pw) {
        const user = env.get('CPS_WEB_USER') || 'admin';
        msg.headers.Authorization = 'Basic ' + Buffer.from(user + ':' + pw).toString('base64');
    }
    msg.payload = body === undefined ? '' : body;
    return msg;
};

const table = (cols, rows, empty) => {
    if (!rows.length) return `<div class="cps-empty">${esc(empty || 'Nothing yet')}</div>`;
    const head = cols.map((c) => `<th${c.right ? ' class="r"' : ''}>${esc(c.label)}</th>`).join('');
    const body = rows.map((r) => '<tr>' + cols.map((c) => {
        const v = c.html ? c.html(r) : esc(c.get ? c.get(r) : r[c.key]);
        return `<td${c.right ? ' class="r"' : ''}>${v}</td>`;
    }).join('') + '</tr>').join('');
    return `<div class="cps-scroll"><table class="cps-tbl"><thead><tr>${head}</tr></thead><tbody>${body}</tbody></table></div>`;
};

const chip = (text, kind) => `<span class="cps-chip ${esc(kind)}">${esc(text)}</span>`;

// "nice" axis ticks
const ticks = (lo, hi, n) => {
    const span = hi - lo || 1;
    const step0 = span / n;
    const mag = Math.pow(10, Math.floor(Math.log10(step0)));
    const step = [1, 2, 2.5, 5, 10].map((m) => m * mag).find((s) => span / s <= n) || 10 * mag;
    const out = [];
    for (let v = Math.ceil(lo / step) * step; v <= hi + step * 1e-9; v += step) out.push(Number(v.toFixed(10)));
    return out;
};

const minmax = (arr) => {
    let lo = Infinity, hi = -Infinity;
    for (const v of arr) { if (v < lo) lo = v; if (v > hi) hi = v; }
    return [lo, hi];
};

// o: {title, xlabel, ylabel, series: [{name, color, points: [[x, y]], dash, width,
//                                    step, marker: 'circle'|'square', line: false, tip: (p) => text}],
//     band: [x0, x1], hlines: [{y, color, label}], height, bars: true, wide: true}
const chart = (o) => {
    const W = o.width || 640, H = o.height || 270, L = 66, R = 14, T = 24, B = 46;
    const series = o.series.map((s) => ({ ...s, points: (s.points || []).filter((p) => p[1] !== null && p[1] !== undefined && !Number.isNaN(p[1])) }));
    const pts = series.flatMap((s) => s.points);
    if (!pts.length) return `<div class="cps-chart"><div class="cps-ctitle">${esc(o.title)}</div><div class="cps-empty">No data</div></div>`;
    let [x0, x1] = minmax(pts.map((p) => p[0]));
    if (o.xmin !== undefined) x0 = o.xmin;
    if (o.xmax !== undefined) x1 = o.xmax;
    let [y0, y1] = minmax(pts.map((p) => p[1]).concat((o.hlines || []).map((h) => h.y)));
    if (o.ymin !== undefined) y0 = Math.min(y0, o.ymin);
    if (o.bars) { const w = (x1 - x0) / Math.max(pts.length - 1, 1); x0 -= w / 2; x1 += w / 2; }
    if (x1 === x0) { x0 -= 1; x1 += 1; }
    if (y1 === y0) { y0 -= Math.abs(y0) * 0.01 || 0.5; y1 += Math.abs(y1) * 0.01 || 0.5; }
    const pad = (y1 - y0) * 0.08;
    if (o.ymin === undefined) y0 -= pad;
    y1 += pad;
    const X = (x) => L + (x - x0) / (x1 - x0) * (W - L - R);
    const Y = (y) => T + (1 - (y - y0) / (y1 - y0)) * (H - T - B);
    let g = '';
    if (o.band) {
        const a = X(Math.max(o.band[0], x0)), b = X(Math.min(o.band[1], x1));
        if (b > a) g += `<rect x="${a}" y="${T}" width="${b - a}" height="${H - T - B}" class="cps-band"/>`;
    }
    for (const v of ticks(y0, y1, 5)) {
        g += `<line x1="${L}" x2="${W - R}" y1="${Y(v)}" y2="${Y(v)}" class="cps-grid"/>` +
             `<text x="${L - 6}" y="${Y(v) + 4}" text-anchor="end" class="cps-tick">${esc(String(v))}</text>`;
    }
    const xt = o.xticks ? o.xticks.filter((v) => v >= x0 && v <= x1)
        : ticks(x0, x1, W > 900 ? 12 : 6).filter((v) => !o.xint || Number.isInteger(v));
    for (const v of xt) {
        g += `<text x="${X(v)}" y="${H - B + 19}" text-anchor="middle" class="cps-tick">${esc(String(v))}</text>`;
    }
    for (const h of o.hlines || []) {
        g += `<line x1="${L}" x2="${W - R}" y1="${Y(h.y)}" y2="${Y(h.y)}" stroke="${h.color || '#666'}" stroke-dasharray="5 4" stroke-width="1.2"/>`;
    }
    if (o.bars) {
        const n = Math.max(...series.map((s) => s.points.length));
        const bw = Math.max(1, (W - L - R) / Math.max(n, 1) * 0.8);
        for (const s of series) {
            for (const p of s.points) {
                const y = Y(Math.max(p[1], y0)), base = Y(Math.max(y0, 0));
                g += `<rect x="${X(p[0]) - bw / 2}" y="${Math.min(y, base)}" width="${bw}" height="${Math.abs(base - y)}" fill="${p[2] || s.color}"/>`;
            }
        }
    } else {
        for (const s of series) {
            const P = s.points;
            if (!P.length) continue;
            let d;
            if (s.step) {
                // steps centred on each point (as matplotlib's steps-mid)
                const mid = (i) => i < 0 ? P[0][0] - (P.length > 1 ? (P[1][0] - P[0][0]) / 2 : 0.5)
                    : i >= P.length - 1 ? P[P.length - 1][0] + (P.length > 1 ? (P[P.length - 1][0] - P[P.length - 2][0]) / 2 : 0.5)
                    : (P[i][0] + P[i + 1][0]) / 2;
                d = `M${X(mid(-1)).toFixed(1)} ${Y(P[0][1]).toFixed(1)}H${X(mid(0)).toFixed(1)}` +
                    P.slice(1).map((p, k) => `V${Y(p[1]).toFixed(1)}H${X(mid(k + 1)).toFixed(1)}`).join('');
            } else {
                d = P.map((p, i) => `${i ? 'L' : 'M'}${X(p[0]).toFixed(1)} ${Y(p[1]).toFixed(1)}`).join('');
            }
            if (s.line !== false) g += `<path d="${d}" fill="none" stroke="${s.color}" stroke-width="${s.width || 1.8}"${s.dash ? ' stroke-dasharray="5 4"' : ''}/>`;
            if (s.marker && P.length <= 400) {
                const tip = s.tip || ((p) => `${s.name}: ${p[0]}, ${p[1]}`);
                for (const p of P) {
                    const x = X(p[0]), y = Y(p[1]), t = `<title>${esc(tip(p))}</title>`;
                    g += s.marker === 'square'
                        ? `<rect x="${(x - 4.5).toFixed(1)}" y="${(y - 4.5).toFixed(1)}" width="9" height="9" fill="${p[2] || s.color}">${t}</rect>`
                        : `<circle cx="${x.toFixed(1)}" cy="${y.toFixed(1)}" r="3.6" fill="${p[2] || s.color}">${t}</circle>`;
                }
            }
        }
    }
    g += `<line x1="${L}" x2="${L}" y1="${T}" y2="${H - B}" class="cps-axis"/><line x1="${L}" x2="${W - R}" y1="${H - B}" y2="${H - B}" class="cps-axis"/>`;
    if (o.xlabel) g += `<text x="${(L + W - R) / 2}" y="${H - 6}" text-anchor="middle" class="cps-lbl">${esc(o.xlabel)}</text>`;
    if (o.ylabel) g += `<text x="16" y="${(T + H - B) / 2}" text-anchor="middle" class="cps-lbl" transform="rotate(-90 16 ${(T + H - B) / 2})">${esc(o.ylabel)}</text>`;
    const legend = series.filter((s) => s.name).map((s) =>
        `<span class="cps-key"><i style="background:${s.color}"></i>${esc(s.name)}</span>`).join('') +
        (o.hlines || []).filter((h) => h.label).map((h) => `<span class="cps-key"><i class="dash" style="border-color:${h.color || '#666'}"></i>${esc(h.label)}</span>`).join('') +
        (o.band ? '<span class="cps-key"><i class="band"></i>attack window</span>' : '');
    return `<div class="cps-chart${o.wide ? ' wide' : ''}"><div class="cps-ctitle">${esc(o.title)}</div>` +
           `<svg viewBox="0 0 ${W} ${H}" preserveAspectRatio="xMidYMid meet" role="img" aria-label="${esc(o.title)}">${g}</svg>` +
           `<div class="cps-legend">${legend}</div></div>`;
};

// Voltage of every bus at one moment, as Fig. 8 of the technical report: true (GridPACK), the
// control center's estimate, and the PMU values as received (p from /api/runs/<id>/profile or live.json)
const profile = (p) => {
    if (!p || !p.true || !p.buses) return '<div class="cps-empty">No voltages yet</div>';
    const B = p.buses, at = {};
    B.forEach((b, i) => { at[b] = i; });
    const removed = new Set(p.removed || []);
    const tip = (what) => (q) => `bus ${q[0]}: ${what} ${num(q[1], 4)} pu`;
    const series = [
        { name: 'true (GridPACK)', color: '#1565c0', marker: 'circle', points: B.map((b, i) => [b, p.true[i]]), tip: tip('true') },
        { name: 'seen by the control center (estimate)', color: '#e53935', step: true, width: 1.6,
          points: p.est ? B.map((b, i) => [b, p.est[i]]) : [] },
        { name: 'received from the PMU', color: '#ef6c00', marker: 'square', line: false,
          points: (p.rx || []).map(([b, v]) => [b, v, removed.has(b) ? '#8e24aa' : '#ef6c00']), tip: tip('received') },
    ];
    if (removed.size) series.push({ name: 'removed as bad data', color: '#8e24aa', line: false, points: [] });
    let rxErr = null, estErr = null, sum = 0;
    for (const [b, v] of p.rx || []) {
        const d = Math.abs(v - p.true[at[b]]);
        if (!rxErr || d > rxErr[1]) rxErr = [b, d];
    }
    if (p.est) B.forEach((b, i) => { const d = Math.abs(p.est[i] - p.true[i]); sum += d; if (!estErr || d > estErr[1]) estErr = [b, d]; });
    const k = [
        kpi('Moment', `${num(p.t, 3)} s`, '', 'time stamp of the PMU set; the true voltages are the grid state at ' + num(p.t_true, 3) + ' s, which the PMUs of this set sampled'),
        kpi('PMUs received', `${(p.rx || []).length}${p.pmus_expected ? ' of ' + p.pmus_expected : ''}`, ''),
        kpi('Largest |received − true|', rxErr ? `${num(rxErr[1], 4)} pu (bus ${esc(rxErr[0])})` : '–', rxErr && rxErr[1] > 0.01 ? 'bad' : 'good'),
        kpi('Largest |estimate − true|', estErr ? `${num(estErr[1], 4)} pu (bus ${esc(estErr[0])})` : '–', estErr && estErr[1] > 0.01 ? 'bad' : 'good'),
        kpi('Mean |estimate − true|', p.est ? num(sum / B.length, 5) + ' pu' : '–', ''),
        kpi('Removed as bad data', removed.size ? esc([...removed].join(', ')) : 'none', removed.size ? 'warn' : ''),
    ];
    const worst = (p.rx || []).map(([b, v]) => ({ b, v, tr: p.true[at[b]], es: p.est ? p.est[at[b]] : null }))
        .sort((x, y) => Math.abs(y.v - y.tr) - Math.abs(x.v - x.tr)).slice(0, 5);
    const tbl = table([
        { label: 'Bus', get: (r) => r.b + (removed.has(r.b) ? ' (removed)' : ''), right: true },
        { label: 'True (pu)', get: (r) => num(r.tr, 4), right: true },
        { label: 'Received (pu)', get: (r) => num(r.v, 4), right: true },
        { label: 'Estimated (pu)', get: (r) => num(r.es, 4), right: true },
        { label: 'Received − true', get: (r) => num(r.v - r.tr, 4), right: true },
    ], worst, 'No PMU values');
    return `<div class="cps-kpis">${k.join('')}</div>` +
        `<div class="cps-charts">${chart({ title: `Voltage at every bus, t = ${num(p.t, 3)} s`, xlabel: 'bus', ylabel: 'voltage (pu)',
            wide: true, width: 1280, height: 380, series, xint: true, xticks: B.length <= 40 ? B : undefined,
            xmin: Math.min(...B) - 0.5, xmax: Math.max(...B) + 0.5,
            hlines: [{ y: p.vmax, color: '#555', label: 'limits ' + p.vmin + ' / ' + p.vmax }, { y: p.vmin, color: '#555' }] })}</div>` +
        `<div class="cps-line sub">Blue: the voltage GridPACK computed (the truth). Orange squares: what each PMU delivered over the NS-3 network,
attacks included (purple: removed as bad data). Red: what the control center sees, its state estimate for every bus from the
received PMU values; buses without a PMU are only seen this way.</div>` +
        `<div class="cps-sect">PMU buses where received and true differ most</div>${tbl}`;
};

const kpi = (label, value, kind, hint) =>
