  k.push(cps.kpi('Highest frequency', dy.f_max_hz == null ? '–' : cps.num(dy.f_max_hz, 3) + ' Hz', dy.f_max_hz > 60.5 ? 'bad' : dy.f_max_hz > 60.2 ? 'warn' : 'good'));
  k.push(cps.kpi('Final frequency', dy.f_final_hz == null ? '–' : cps.num(dy.f_final_hz, 3) + ' Hz', ''));
