c.push(cps.chart({title: dyn ? 'GridPACK dynamic simulation per grid step' : 'GridPACK power flow per grid step', xlabel: 'time (s)', ylabel: 'ms',
  series: [{name: dyn ? 'MPI integration (dsf_server)' : 'MPI solve (pf_server)', color: '#2e7d32', points: gp.map(p => [p[0], p[2]])},
           {name: 'step incl. data exchange', color: '#90a4ae', points: gp.map(p => [p[0], p[1]])}], ymin: 0}));
if (s.latency_hist) c.push(cps.chart({title: 'PMU → PDC latency', xlabel: 'latency (ms)', ylabel: 'frames', bars: true, ymin: 0,
  series: [{name: '', color: '#00897b', points: s.latency_hist}]}));
c.push(cps.chart({title: 'PDC set completeness', xlabel: 'time (s)', ylabel: 'share of PMUs', band, ymin: 0,
  series: [{name: '', color: '#455a64', points: s.completeness}]}));
if (s.pmus && s.pmus.length <= 400) c.push(cps.chart({title: 'Delivery per PMU (attacked in red)', xlabel: 'PMU (in placement order)', ylabel: 'delivered', bars: true, ymin: 0,
  series: [{name: '', color: '#43a047', points: s.pmus.map((p, i) => [i + 1, p.delivery, p.attacked_frames ? '#e53935' : '#43a047'])}]}));
return {payload: `<div class="cps-charts">${c.join('')}</div>`};

const cps = global.get('cps'); if (!cps) return null;
const q = [];
const run = flow.get('live_run'), bus = flow.get('live_bus');
if (run) q.push('run=' + encodeURIComponent(run));
if (bus) q.push('bus=' + bus);
return cps.api({cps: 'live'}, 'GET', '/api/live' + (q.length ? '?' + q.join('&') : ''));

const b = parseInt(msg.payload, 10);
flow.set('live_bus', b > 0 ? b : null);
flow.set('live_sig', null);
return {payload: Date.now()};

const cps = global.get('cps');
if (msg.statusCode !== 200) return null;
const L = msg.payload.live, active = msg.payload.active || [];
if (!L || L.starting) {
  const txt = L ? 'Starting ' + cps.esc(L.run_id) + ' ...' : 'No experiment yet. Queue one on the Experiments page.';
  return [{payload: {html: `<div class="cps-empty">${txt}</div>`, active, selected: flow.get('live_run')}}, {payload: ''}, {payload: ''}, {payload: ''}];
}
const sig = [L.run_id, L.t, L.sets, L.bus, L.done, active.join(',')].join('|');
if (sig === flow.get('live_sig')) return null;
flow.set('live_sig', sig);
if (!flow.get('live_run') || !active.includes(flow.get('live_run'))) flow.set('live_run', active.length ? L.run_id : null);
const pct = Math.min(100, 100 * L.t / L.duration);
const last = L.last || {};
const tmax = L.truth_max.length ? L.truth_max[L.truth_max.length - 1] : null;
const viol = tmax && (tmax[1] > L.vmax || tmax[1] < L.vmin);
const issued = L.commands.filter(c => c.issued_t != null).length, applied = L.commands.filter(c => c.applied_t != null).length;
const k = [
  cps.kpi('Simulated time', cps.num(L.t, 2) + ' / ' + cps.num(L.duration, 0) + ' s', ''),
  cps.kpi('Highest true V now', tmax ? cps.num(tmax[1], 3) + ' pu (bus ' + cps.esc(tmax[2]) + ')' : '–', viol ? 'bad' : 'good'),
  cps.kpi('Highest estimated V', last.max_v != null ? cps.num(last.max_v, 3) + ' pu (bus ' + cps.esc(last.max_bus) + ')' : '–', last.viol ? 'warn' : ''),
  cps.kpi('Bad data alarms', cps.esc(L.alarms) + ' of ' + cps.esc(L.sets) + ' sets', L.alarms ? 'warn' : 'good'),
  cps.kpi('Chi-square J / threshold', last.J != null ? cps.num(last.J, 1) + ' / ' + cps.num(last.thr, 1) : '–', last.alarm ? 'bad' : ''),
  cps.kpi('PDC set completeness', last.complete != null ? cps.num(100 * last.complete, 0) + '%' : '–', last.complete < 1 ? 'warn' : 'good'),
  cps.kpi('Commands issued / applied', issued + ' / ' + applied, ''),
  cps.kpi('GridPACK MPI ranks', cps.esc(L.mpi_np || '–'), ''),
];
const dyn = L.mode === 'dynamic';
const fl = dyn && L.freq && L.freq.length ? L.freq[L.freq.length - 1] : null;
const sp = dyn && L.angle_spread && L.angle_spread.length ? L.angle_spread[L.angle_spread.length - 1] : null;
if (dyn) {
  const fmin = L.freq && L.freq.length ? Math.min(...L.freq.map(p => p[2])) : null;
  k.push(cps.kpi('System frequency', fl ? cps.num(fl[1], 3) + ' Hz' : '–', fl && Math.abs(fl[1] - 60) > 0.5 ? 'bad' : fl && Math.abs(fl[1] - 60) > 0.1 ? 'warn' : 'good',
    'centre-of-inertia frequency of the generators'));
  k.push(cps.kpi('Lowest frequency so far', fmin != null ? cps.num(fmin, 3) + ' Hz' : '–', fmin != null && fmin < 59.5 ? 'bad' : fmin != null && fmin < 59.8 ? 'warn' : 'good'));
  const sp0 = L.angle_spread && L.angle_spread.length ? L.angle_spread[0][1] : null;
  k.push(cps.kpi('Rotor angle spread', sp ? cps.num(sp[1], 1) + '° (start ' + cps.num(sp0, 1) + '°)' : '–', sp && sp[1] - sp0 > 120 ? 'bad' : sp && sp[1] - sp0 > 60 ? 'warn' : '',
    'largest minus smallest rotor angle of the generators in service'));
}
const state = L.done ? cps.chip('finished', 'ok') : cps.chip('running', 'run');
const head = `<div class="cps-title">${cps.esc(L.name)} <span class="sub">${cps.esc(L.grid)} · ${cps.esc(L.run_id)}</span> ${state}</div>
<div class="cps-progress"><div style="width:${pct.toFixed(1)}%"></div></div>
<div class="cps-tags">${[dyn ? 'dynamic simulation' : 'quasi-steady state', L.attack !== 'none' ? 'attack ' + L.attack : 'no attack', L.event !== 'none' ? 'event ' + L.event : null]
  .filter(Boolean).map(t => cps.chip(t, 'tag')).join(' ')}</div>
<div class="cps-kpis">${k.join('')}</div>
${active.length > 1 ? '<div class="cps-line sub">Several experiments are running; pick one above.</div>' : ''}
${L.done ? '<div class="cps-line sub">The experiment has finished; all results are on the Results page.</div>' : ''}`;
const xr = {xmin: 0, xmax: L.duration};
const band = L.attack_window || undefined;
const c = [];
c.push(cps.chart({title: `Voltage at bus ${L.bus}`, xlabel: 'time (s)', ylabel: 'pu', band, ...xr,
  series: [{name: 'true (GridPACK)', color: '#1565c0', points: L.truth}, {name: 'estimated (control center)', color: '#e53935', points: L.estimate}],
  hlines: [{y: L.vmax, color: '#555', label: 'V max'}]}));
c.push(cps.chart({title: 'Highest bus voltage', xlabel: 'time (s)', ylabel: 'pu', band, ...xr,
  series: [{name: 'true', color: '#1565c0', points: L.truth_max.map(p => [p[0], p[1]])}, {name: 'estimated', color: '#e53935', points: L.est_max}],
  hlines: [{y: L.vmax, color: '#555', label: 'V max'}]}));
c.push(cps.chart({title: 'Bad data test (chi-square)', xlabel: 'time (s)', ylabel: 'J', band, ...xr,
  series: [{name: 'J', color: '#6a1b9a', points: L.chi2.map(p => [p[0], p[1]])},
           {name: 'threshold', color: '#ef6c00', dash: true, points: L.chi2.map(p => [p[0], p[2]])}]}));
if (dyn) {
  c.push(cps.chart({title: 'Frequency', xlabel: 'time (s)', ylabel: 'Hz', band, ...xr,
    series: [{name: 'centre of inertia', color: '#00838f', points: (L.freq || []).map(p => [p[0], p[1]])},
             {name: 'lowest bus', color: '#ef6c00', dash: true, points: (L.freq || []).map(p => [p[0], p[2]])},
             {name: 'highest bus', color: '#8e24aa', dash: true, points: (L.freq || []).map(p => [p[0], p[3]])}],
    hlines: [{y: 60, color: '#555', label: '60 Hz'}]}));
  c.push(cps.chart({title: 'Rotor angle spread', xlabel: 'time (s)', ylabel: 'degrees', band, ...xr,
    series: [{name: '', color: '#5d4037', points: L.angle_spread || []}]}));
}
c.push(cps.chart({title: 'PDC set completeness', xlabel: 'time (s)', ylabel: 'share of PMUs', band, ymin: 0, ...xr,
  series: [{name: '', color: '#455a64', points: L.completeness}]}));
const rows = L.events.map(e => ({...e, kind: 'event'})).concat(L.commands.map(c => ({...c, kind: 'command'})));
const cmds = cps.table([
  {label: 'Kind', get: r => r.kind},
  {label: 'Generator', get: r => r.gen_bus, right: true},
  {label: 'Setpoint (pu)', get: r => r.vset, right: true},
  {label: 'Issued (s)', get: r => r.issued_t == null ? '' : cps.num(r.issued_t, 3), right: true},
  {label: 'Delivered (s)', get: r => r.delivered_t == null ? '' : cps.num(r.delivered_t, 3), right: true},
  {label: 'Applied (s)', get: r => r.applied_t == null ? 'pending' : cps.num(r.applied_t, 2), right: true},
  {label: 'Reason', get: r => r.reason},
], rows, 'No events or commands yet');
// every bus at the last estimate: true, received from the PMUs, seen by the control center
const prof = L.profile ? cps.profile({...L.profile, vmin: L.vmin, vmax: L.vmax}) : '<div class="cps-empty">Waiting for the first estimate</div>';
return [{payload: {html: head, active, selected: L.run_id}}, {payload: `<div class="cps-charts">${c.join('')}</div>`}, {payload: cmds}, {payload: prof}];

flow.set('live_run', msg.payload);
flow.set('live_bus', null);
flow.set('live_sig', null);
return {payload: Date.now()};

const cps = global.get('cps'); if (!cps) return null;
if (msg.topic === 'init') return [[cps.api({cps: 'form_grids'}, 'GET', '/api/grids'), cps.api({cps: 'form_cluster'}, 'GET', '/api/cluster')]];
if (msg.topic === 'grid') return cps.api({cps: 'form_grid'}, 'GET', '/api/grids/' + encodeURIComponent(msg.payload));
if (msg.topic === 'run') return cps.api({cps: 'form_run'}, 'POST', '/api/scenarios',
  {filename: 'dashboard form', content: JSON.stringify(msg.payload), encoding: 'text'});
return null;

// one state object for the experiment form: grids, cluster, the chosen grid's buses and
// lines, and the answer to the last run (one message, so updates cannot overtake each other)
const cps = global.get('cps');
const st = flow.get('form_state') || {};
const ok = msg.statusCode === 200;
const detail = () => { const d = msg.payload && msg.payload.detail; return typeof d === 'string' ? d : JSON.stringify(d || msg.payload || msg.statusCode); };
switch (msg.cps) {
  case 'grids': case 'form_grids': {
    if (!ok) return null;
    const g = msg.payload.map(x => ({id: x.id, name: x.name, buses: x.buses}));
    if (msg.cps === 'grids' && JSON.stringify(g) === JSON.stringify(st.grids)) return null;
    st.grids = g; break;
  }
  case 'cluster': case 'form_cluster': {
    if (!ok) return null;
    const c = {mpi_slots: msg.payload.mpi_slots, default_np: msg.payload.default_np,
               nodes: (msg.payload.nodes || []).filter(n => n.mpi_slots).length};
    if (msg.cps === 'cluster' && JSON.stringify(c) === JSON.stringify(st.cluster)) return null;
    st.cluster = c; break;
  }
  case 'form_grid':
    if (!ok) { st.result = {n: ((st.result || {}).n || 0) + 1, ok: false, text: detail()}; break; }
    st.info = {id: msg.payload.id, bus_ids: msg.payload.bus_ids, gens: msg.payload.gens, lines: msg.payload.lines};
    break;
  case 'form_run': {
    const n = ((st.result || {}).n || 0) + 1;
    if (!ok) { st.result = {n, ok: false, text: detail()}; break; }
    const j = msg.payload;
    st.result = {n, ok: true, text: 'Queued: ' + j.map(x => x.request.name + ' on ' + x.grid +
      (x.request.solver === 'gridpack' ? ' with ' + x.request.mpi_np + ' MPI rank' + (x.request.mpi_np > 1 ? 's' : '') : '')).join(', ') +
      '. It starts as soon as MPI slots are free; the queue is below.'};
    break;
  }
  default: return null;
}
flow.set('form_state', st);
return {payload: st};

const cps = global.get('cps'); if (!cps) return null;
if (msg.topic === 'init') return cps.api({cps: 'settings_get'}, 'GET', '/api/cluster/settings');
if (msg.topic === 'save') return cps.api({cps: 'settings_put'}, 'PUT', '/api/cluster/settings', msg.payload);
if (msg.topic === 'reset') return cps.api({cps: 'settings_reset'}, 'DELETE', '/api/cluster/settings');
return null;

const cps = global.get('cps');
const st = flow.get('settings_state') || {};
const ok = msg.statusCode === 200;
const n = ((st.result || {}).n || 0) + 1;
const detail = () => { const d = msg.payload && msg.payload.detail;
  return Array.isArray(d) ? d.map(e => (e.loc || []).slice(1).join('.') + ': ' + e.msg).join('; ') : typeof d === 'string' ? d : JSON.stringify(msg.payload); };
let again = null;
if (msg.cps === 'settings_get') {
  if (!ok) return null;
  st.settings = msg.payload; st.settings_n = (st.settings_n || 0) + 1;
} else if (msg.cps === 'settings_put') {
  if (ok) {
    const r = msg.payload;
    st.result = {n, ok: !r.unreachable.length, text: 'Saved. MPI slots: ' + r.mpi_slots + '.' + (r.unreachable.length
      ? ' Not reachable over ssh: ' + r.unreachable.join(', ') + ' (installed with --role node? /srv/cps mounted? host name resolvable?)' : '')};
    again = cps.api({cps: 'settings_get'}, 'GET', '/api/cluster/settings');
  } else st.result = {n, ok: false, text: detail()};
} else if (msg.cps === 'settings_reset') {
  if (ok) { st.settings = msg.payload; st.settings_n = (st.settings_n || 0) + 1; st.result = {n, ok: true, text: 'Using /etc/cps/cps.env again.'}; }
  else st.result = {n, ok: false, text: detail()};
} else return null;
flow.set('settings_state', st);
return [{payload: st}, again];

// Inside page: what GridPACK, NS-3, HELICS and the control center are doing right now.
// Input: the /api/live answer (msg.payload.live.inside). Outputs: HELICS, GridPACK, NS-3,
// control center, log.
const cps = global.get('cps');
if (msg.statusCode !== 200) return null;
const L = msg.payload.live;
const empty = (t) => Array(5).fill(null).map((_, i) => ({payload: i === 0 ? `<div class="cps-empty">${t}</div>` : ''}));
if (!L || L.starting) return empty('No experiment yet. Start one on the Experiments page; this page then shows what happens inside it.');
const I = L.inside;
if (!I) return empty('This experiment was run before the Inside view existed.');
const sig = [L.run_id, L.t, L.done, (I.trace || []).length].join('|');
if (sig === flow.get('inside_sig')) return null;
flow.set('inside_sig', sig);
const esc = cps.esc, num = cps.num;
const kb = (b) => b > 1048576 ? num(b / 1048576, 1) + ' MB' : num(b / 1024, 1) + ' kB';
const head = `<div class="cps-title">${esc(L.name)} <span class="sub">${esc(L.grid)} · ${esc(L.run_id)} · simulated ${num(L.t, 2)} / ${num(L.duration, 0)} s</span> ${L.done ? cps.chip('finished', 'ok') : cps.chip('running', 'run')}</div>`;

// ---------------------------------------------------------------- HELICS
const H = I.helics || {}, T = H.topics || {};
const fedTime = {};
for (const f of H.federates || []) fedTime[f.name] = f;
const boxes = {grid: {x: 10, y: 70, label: 'Grid federate', sub: 'GridPACK'}, ns3_network: {x: 350, y: 70, label: 'NS-3 network', sub: 'PMUs, links, PDC'},
               control_center: {x: 690, y: 70, label: 'Control center', sub: 'estimation, control'}, observer: {x: 350, y: 270, label: 'Observer', sub: 'this dashboard'}};
const W = 200, Hh = 84;
let svg = '';
const arrow = (x1, y1, x2, y2, color) => `<line x1="${x1}" y1="${y1}" x2="${x2}" y2="${y2}" stroke="${color}" stroke-width="2" marker-end="url(#ah)"/>`;
// topic labels sit above (measurements) or below (commands) the arrows between the boxes
const lab = (k, x, y) => { const t = T[k] || {};
  return `<text x="${x}" y="${y}" text-anchor="middle" class="cps-alabel"><tspan x="${x}" class="tn">${esc(k)}</tspan><tspan x="${x}" dy="13">${t.count || 0} msgs · ${kb(t.bytes || 0)}</tspan></text>`; };
svg += arrow(212, 96, 348, 96, '#1565c0') + lab('grid/meas', 280, 70);
svg += arrow(552, 96, 688, 96, '#1565c0') + lab('ns3/pdc', 620, 70);
svg += arrow(688, 134, 552, 134, '#c62828') + lab('cc/commands', 620, 152);
svg += arrow(348, 134, 212, 134, '#c62828') + lab('ns3/cmd_delivered', 280, 152);
svg += arrow(110, 156, 360, 274, '#b0bec5') + arrow(450, 156, 450, 266, '#b0bec5') + arrow(790, 156, 540, 274, '#b0bec5');
svg += `<text x="200" y="230" text-anchor="middle" class="cps-alabel">grid/status</text><text x="456" y="215" class="cps-alabel">ns3/status</text><text x="700" y="230" text-anchor="middle" class="cps-alabel">cc/status</text>`;
for (const [name, b] of Object.entries(boxes)) {
  const f = fedTime[name];
  svg += `<rect x="${b.x}" y="${b.y}" width="${W}" height="${Hh}" rx="8" class="cps-fbox ${name === 'observer' ? 'obs' : ''}"/>` +
         `<text x="${b.x + W / 2}" y="${b.y + 24}" text-anchor="middle" class="cps-ftitle">${b.label}</text>` +
         `<text x="${b.x + W / 2}" y="${b.y + 44}" text-anchor="middle" class="cps-fsub">${b.sub}${f && f.host ? ' · on ' + esc(f.host) : ''}</text>` +
         `<text x="${b.x + W / 2}" y="${b.y + 68}" text-anchor="middle" class="cps-ftime">${f && f.granted != null ? 'granted t = ' + num(f.granted, 3) + ' s' : ''}</text>`;
}
const helics = `${head}<svg viewBox="0 0 900 370" class="cps-flow"><defs><marker id="ah" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="7" markerHeight="7" orient="auto"><path d="M0,0 L10,5 L0,10 z" fill="#546e7a"/></marker></defs>${svg}</svg>
<div class="cps-line sub">HELICS keeps every federate on one simulated clock: each asks for its next time step and is granted it only when
the data it needs has arrived. Broker port ${esc(H.port || '')} (ZeroMQ). Blue: measurements; red: commands; grey: copies for this dashboard.
${(H.federates || []).length ? '' : 'Federate times appear while the experiment runs.'}</div>`;

// ---------------------------------------------------------------- GridPACK
const G = I.gridpack || {}, g = G.last || {};
let gp = '<div class="cps-empty">Waiting for the first grid step</div>';
if (g.server) {
  const ranks = G.ranks || [];
  const maxb = Math.max(1, ...ranks.map(r => r.buses));
  const rk = ranks.map(r => `<div class="cps-rank"><span class="rn">rank ${r.rank}</span><span class="rh">${esc(r.host)}</span>
    <span class="rb"><i style="width:${(100 * r.buses / maxb).toFixed(0)}%"></i></span><span class="rv">${r.buses} buses · ${r.branches} branches</span></div>`).join('');
  const k = [
    cps.kpi('Solver', esc(g.server), ''),
    cps.kpi('MPI ranks', esc(g.ranks), ''),
    cps.kpi(I.mode === 'dynamic' ? 'Integration this frame' : 'Newton iterations', I.mode === 'dynamic' ? esc(g.steps) + ' × ' + num(g.dt_ms, 2) + ' ms' : esc(Math.max(0, (g.iterations || []).length - 1)), g.converged === false ? 'bad' : 'good'),
    cps.kpi('GridPACK time (MPI)', g.t_mpi_ms != null ? num(g.t_mpi_ms, 2) + ' ms' : '–', ''),
    cps.kpi('Step incl. data exchange', num(g.t_step_ms, 2) + ' ms', ''),
    cps.kpi('Load', num(g.load_mw, 0) + ' MW', ''),
    cps.kpi('Highest / lowest V', num(g.max_v[0], 3) + ' (bus ' + esc(g.max_v[1]) + ') / ' + num(g.min_v[0], 3) + ' (bus ' + esc(g.min_v[1]) + ')', ''),
  ];
  const charts = [];
  if (I.mode !== 'dynamic' && (g.iterations || []).length && g.iterations[0][1] != null) {
    charts.push(cps.chart({title: 'Newton-Raphson convergence of the last power flow', xlabel: 'iteration', ylabel: 'log10 mismatch (pu)', height: 220,
      series: [{name: 'largest power mismatch', color: '#2e7d32', points: g.iterations.map(p => [p[0], Math.log10(Math.max(p[1], 1e-16))])}],
      hlines: [{y: -6, color: '#ef6c00', label: 'tolerance 1e-6'}]}));
  }
  const hist = G.history || [];
  charts.push(cps.chart({title: I.mode === 'dynamic' ? 'GridPACK time per PMU frame' : 'GridPACK time per grid step', xlabel: 'simulated time (s)', ylabel: 'ms', ymin: 0, height: 220,
    series: [{name: 'MPI computation', color: '#2e7d32', points: hist.map(p => [p[0], p[1]])}, {name: 'incl. data exchange', color: '#90a4ae', points: hist.map(p => [p[0], p[2]])}]}));
  gp = `<div class="cps-kpis">${k.join('')}</div>
<div class="cps-sect">How the grid is split over the MPI ranks</div>${rk || '<div class="cps-empty">single process</div>'}
<div class="cps-line sub">${I.mode === 'dynamic'
    ? 'Each PMU frame GridPACK integrates the generator, exciter and governor equations in small steps; every step solves the network equations (Y·V = I) on all ranks together.'
    : 'Each grid step GridPACK solves the power flow with Newton-Raphson: it builds the Jacobian on all ranks, solves the linear system with PETSc/MUMPS and updates the voltages until the power mismatch is below the tolerance.'}</div>
<div class="cps-charts">${charts.join('')}</div>`;
}

// ---------------------------------------------------------------- NS-3
const N = I.ns3;
let ns = '<div class="cps-empty">Waiting for the network federate</div>';
if (N) {
  const cells = N.pmus.map(p => {
    const [bus, delay, sent, dlv, late, drop, atk, lat, rec] = p;
    const r = rec || [0, 0, 0, 0, 0];
    let cls = 'ok';
    if (r[0] === 0) cls = 'idle';
    else if (r[3] > 0) cls = 'drop';
    else if (r[1] < r[0] - r[2] || r[2] > 0) cls = r[2] > 0 ? 'late' : 'lost';
    if (r[4] > 0 && cls === 'ok') cls = 'atk';
    const tip = `PMU at bus ${bus} · link ${num(delay, 1)} ms · last latency ${num(lat, 1)} ms · total ${sent} sent, ${dlv} delivered, ${late} late, ${drop} dropped, ${atk} attacked`;
    return `<span class="cps-pmu ${cls}" title="${esc(tip)}">${N.pmus.length <= 80 ? esc(bus) : ''}</span>`;
  }).join('');
  const tot = N.pmus.reduce((a, p) => [a[0] + p[2], a[1] + p[3], a[2] + p[4], a[3] + p[5], a[4] + p[6]], [0, 0, 0, 0, 0]);
  const pdc = N.pdc || {}, cm = N.commands || {};
  const k = [
    cps.kpi('PMU frames sent', esc(tot[0]), ''),
    cps.kpi('Reached the PDC in time', tot[0] ? num(100 * tot[1] / tot[0], 1) + '%' : '–', tot[0] && tot[1] / tot[0] < 0.95 ? 'warn' : 'good'),
    cps.kpi('Late / dropped / attacked', `${tot[2]} / ${tot[3]} / ${tot[4]}`, tot[3] || tot[4] ? 'bad' : ''),
    cps.kpi('PDC sets released', esc(pdc.sets) + ' (' + esc(pdc.complete) + ' complete)', ''),
    cps.kpi('PDC release after', num(pdc.release_ms, 1) + ' ms (wait ' + num(pdc.wait_ms, 0) + ' ms)', ''),
    cps.kpi('Commands sent / delivered', `${cm.sent || 0} / ${cm.delivered || 0}`, cm.sent > cm.delivered ? 'warn' : ''),
    cps.kpi('Attacker', esc((N.attack || {}).type) + ((N.attack || {}).active ? ' · active' : ''), (N.attack || {}).active ? 'bad' : ''),
    cps.kpi('NS-3 events simulated', esc(N.events), ''),
  ];
  const lat = N.pmus.filter(p => p[7] >= 0).map((p, i) => [i + 1, p[7], p[6] > 0 ? '#8e24aa' : '#00897b']);
  ns = `<div class="cps-kpis">${k.join('')}</div>
<div class="cps-sect">PMUs in the last 0.5 s <span class="sub">(hover for details)</span></div>
<div class="cps-pmus">${cells}</div>
<div class="cps-legend"><span class="cps-key"><i class="sq ok"></i>delivered</span><span class="cps-key"><i class="sq late"></i>late</span>
<span class="cps-key"><i class="sq lost"></i>lost / on the way</span><span class="cps-key"><i class="sq drop"></i>dropped by attacker</span><span class="cps-key"><i class="sq atk"></i>falsified or delayed</span></div>
<div class="cps-line sub">Every PMU sends a frame per reporting interval over its own link (own delay, jitter, loss) to the PDC, which waits up to
${num(pdc.wait_ms, 0)} ms for the frames of one time stamp and passes the set to the control center. Commands go back the same way to the generators.</div>
<div class="cps-charts">${cps.chart({title: 'Latency of the last frame of each PMU (purple: attacked)', xlabel: 'PMU (in placement order)', ylabel: 'ms', bars: true, ymin: 0, height: 200, series: [{name: '', color: '#00897b', points: lat}]})}</div>`;
}

// ---------------------------------------------------------------- control center
const C = I.cc || {}, c = C.last;
let cc = '<div class="cps-empty">Waiting for the first measurement set</div>';
if (c) {
  const k = [
    cps.kpi('Measurements used', esc(c.m) + ' from ' + esc(c.pmus) + ' PMUs', ''),
    cps.kpi('States estimated', esc(L.inside && G.last ? G.last.buses : '') + ' bus voltages', ''),
    cps.kpi('Observable', c.obs ? 'yes' : 'no: ' + esc(c.pmus) + ' of ' + esc(c.expected || '?') + ' PMUs arrived', c.obs ? 'good' : 'warn'),
    c.obs ? cps.kpi('Chi-square J / threshold', num(c.J, 1) + ' / ' + num(c.thr, 1), c.alarm ? 'bad' : 'good')
          : cps.kpi('Chi-square J / threshold', 'not tested', ''),
    cps.kpi('Removed PMUs', esc((c.removed || []).join(', ') || 'none'), (c.removed || []).length ? 'warn' : ''),
    cps.kpi('J after removal', num(c.J_final, 1), ''),
    cps.kpi('Estimation time', num(c.est_ms, 2) + ' ms', ''),
    cps.kpi('Set age when processed', num(c.lag_ms, 1) + ' ms', ''),
  ];
  const hist = C.history || [];
  cc = `<div class="cps-kpis">${k.join('')}</div>
<div class="cps-line sub">For every PMU set the control center solves the weighted least-squares state estimate z = H·V, tests the residuals
with chi-square (J above the threshold means bad data), removes the PMU with the largest normalized residual and re-estimates, then checks the
voltages and sends setpoint commands when one is out of limits. A set that misses PMUs can leave part of the grid unobserved
(minimum placement has no spare PMU); such a set cannot be tested for bad data and the chart skips it.</div>
<div class="cps-charts">${cps.chart({title: 'Bad data test per complete set', xlabel: 'simulated time (s)', ylabel: 'J', height: 200,
  series: [{name: 'J', color: '#6a1b9a', points: hist.map(p => [p[0], p[2]])}, {name: 'threshold', color: '#ef6c00', dash: true, points: hist.map(p => [p[0], p[3]])}]})}
${cps.chart({title: 'Estimation time per set', xlabel: 'simulated time (s)', ylabel: 'ms', ymin: 0, height: 200, series: [{name: '', color: '#455a64', points: hist.map(p => [p[0], p[1]])}]})}</div>`;
}

// ---------------------------------------------------------------- log
const kind = {'GridPACK': 'gp', 'NS-3': 'ns', 'Control center': 'cc', 'HELICS': 'hx'};
const line = r => `<div class="row"><span class="t">${num(r[0], 3)} s</span>${cps.chip(r[1], 'eng ' + (kind[r[1]] || ''))}<span class="x">${esc(r[2])}</span></div>`;
const all = (I.trace || []).slice().reverse();
const keyRows = all.filter(r => r[3] !== false), stepRows = all.filter(r => r[3] === false).slice(0, 40);
const log = all.length ? `<div class="cps-sect">Key events</div><div class="cps-trace key">${keyRows.length ? keyRows.map(line).join('') : '<div class="cps-empty">none yet</div>'}</div>
<div class="cps-sect">Every step <span class="sub">(latest first)</span></div><div class="cps-trace">${stepRows.map(line).join('')}</div>`
  : '<div class="cps-empty">Nothing yet</div>';

return [{payload: helics}, {payload: gp}, {payload: ns}, {payload: cc}, {payload: log}];

const cps = global.get('cps');
const id = flow.get('run'); const t = Number(msg.payload);
if (!id || !Number.isFinite(t)) return null;
return cps.api({cps: 'profile'}, 'GET', '/api/runs/' + encodeURIComponent(id) + '/profile?t=' + t);

const cps = global.get('cps');
if (msg.statusCode !== 200) {
  const d = (msg.payload && msg.payload.detail) || 'no data';
  return {payload: {html: `<div class="cps-err">${cps.esc(d)}</div>`, info: null}};
}
const p = msg.payload;
return {payload: {html: cps.profile(p), info: {t: p.t, t_range: p.t_range, step: p.step, marks: p.marks}}};
